entries[1264988] = { ["name"] = "Snowpaw Glimmerfur Prowler", ["text"] = "1.5 sec cast\nSummons and dismisses this mount.\n\"The snowpaw inhabit the frigid afterlives of the Shadowlands, reveling in their frosty environment. Travelers thought lost to the deadly blizzards of Northrend would sometimes miraculously be found alive, proclaiming that they owe their lives to the mysterious foxes that protected them.\"\nVendor:\nCollector Ta'steld\nZone:\nOribos\nCost:\n5000" }
