entries[1265641] = { ["name"] = "Kill or Be Killed", ["text"] = "Unlimited range\nInstant\nWhen you would sustain fatal damage, you instead fly into an unstoppable rage, becoming unkillable and immune to movement-impairing effects for 8 sec as you seek revenge on your would-be killer.\n\nIf you kill your killer in that time, you emerge from your blind rage triumphant, with at least 20% of your max health intact. If you are not victorious, you die.\n\nThis effect can only occur once every 5 min and if your killer is alive when you sustain fatal damage." }
entries[1265644] = { ["name"] = "Stunning Monologue", ["text"] = "100 yd range\nInstant\nStuns nearby opponents long enough to inform them of their mistakes." }
entries[1265645] = { ["name"] = "Kill or Be Killed", ["text"] = "Unlimited range\nInstant\nWhen you would sustain fatal damage, you instead fly into an unstoppable rage, becoming unkillable and immune to movement-impairing effects for 8 sec as you seek revenge on your would-be killer.\n\nIf you kill your killer in that time, you emerge from your blind rage triumphant, with at least 20% of your max health intact. If you are not victorious, you die.\n\nThis effect can only occur once every 5 min and if your killer is alive when you sustain fatal damage." }
entries[1265646] = { ["name"] = "Kill or Be Killed", ["text"] = "Unlimited range\nInstant\nWhen you would sustain fatal damage, you instead fly into an unstoppable rage, becoming unkillable and immune to movement-impairing effects for 8 sec as you seek revenge on your would-be killer.\n\nIf you kill your killer in that time, you emerge from your blind rage triumphant, with at least 20% of your max health intact. If you are not victorious, you die.\n\nThis effect can only occur once every 5 min and if your killer is alive when you sustain fatal damage." }
