entries[1265689] = { ["name"] = "Grim Chorus", ["text"] = "5.5 sec cast\nL'ura shifts the Notes of Despair and begins a Grim Chorus for 20 sec, inflicting 242456 to players within 23 yards of each active Note of Despair .\nEach active Note of Despair afflicts players with Anguish every 2 sec until the Notes of Despair are destroyed." }
