entries[1265692] = { ["name"] = "Resourcefulness", ["text"] = "5 yd range\n2.5 sec cast\nResourcefulness increases the chance of using fewer reagents in a craft. Only reagents that are not bound to you can be affected. Resourcefulness can be increased by equipping a Professions tool and accessories. Spending knowledge points to specialize in certain crafts can boost Resourcefulness related to those recipes." }
