entries[1265713] = { ["name"] = "Knowledge", ["text"] = "5 yd range\n2.5 sec cast\nKnowledge points are spent on Specializations. Specializations grant access to improved gathering, stat bonuses, and more. Knowledge points are earned from gathering at a new node for the first time, quest rewards, gathering nodes, and occasionally treasures." }
